public class AzureNotionFileProvider : INotionFileProvider
{
    private readonly BlobContainerClient _container;

    public AzureNotionFileProvider(BlobContainerClient container)
        => _container = container;

    public async Task<string> UploadFileAsync(Stream content, string fileName, string contentType)
    {
        var blobName = $"{Guid.NewGuid()}/{fileName}";
        var blob = _container.GetBlobClient(blobName);
        await blob.UploadAsync(content, new BlobHttpHeaders { ContentType = contentType });
        return blob.Uri.ToString();
    }

    public Task<string> GetFileUrlAsync(string fileId)
        => Task.FromResult(fileId); // fileId is already a URL in this implementation

    public async Task DeleteFileAsync(string fileId)
    {
        var uri = new Uri(fileId);
        await _container.GetBlobClient(uri.Segments.Last()).DeleteAsync();
    }

    public async Task<long> GetFileSizeAsync(string fileId)
    {
        var props = await _container.GetBlobClient(new Uri(fileId).Segments.Last()).GetPropertiesAsync();
        return props.Value.ContentLength;
    }
}
